insert into naruto_spiritism.seals (id, name, animal, reading, image, hint, sort_order) values
('rat', '子', '鼠', 'NE', '/images/seals/legend/rat.png', '一手食指与中指竖起，另一手握住竖起的两指。', 0),
('ox', '丑', '牛', 'USHI', '/images/seals/legend/ox.png', '两手手指交错，一手平放，另一手食指与小指伸直。', 1),
('tiger', '寅', '虎', 'TORA', '/images/seals/legend/tiger.png', '两手相合，食指竖起相贴，拇指并拢，其余手指交错。', 2),
('hare', '卯', '兔', 'U', '/images/seals/legend/hare.png', '一手食指伸直，另一手小指勾住食指下方，其余手指握拢。', 3),
('dragon', '辰', '龙', 'TATSU', '/images/seals/legend/dragon.png', '两手手指交错下垂，小指伸直相贴，拇指上下相叠。', 4),
('snake', '巳', '蛇', 'MI', '/images/seals/legend/snake.png', '两手手指交错，掌心相合，手指向内收紧。', 5),
('horse', '午', '马', 'UMA', '/images/seals/legend/horse.png', '两手食指指尖相抵，其余手指弯曲交错，形成三角轮廓。', 6),
('ram', '未', '羊', 'HITSUJI', '/images/seals/legend/ram.png', '两手相合，中指和食指向上伸直，其余手指交错收拢。', 7),
('monkey', '申', '猴', 'SARU', '/images/seals/legend/monkey.png', '两手水平相叠，掌心相对，两侧手指向外伸展。', 8),
('bird', '酉', '鸟', 'TORI', '/images/seals/legend/bird.png', '两手中指弯曲相勾，食指和小指相抵，拇指靠拢。', 9),
('dog', '戌', '犬', 'INU', '/images/seals/legend/dog.png', '一手握拳，另一手掌平放在拳头上方。', 10),
('boar', '亥', '猪', 'I', '/images/seals/legend/boar.png', '两手手指弯曲向下，指节相靠，拇指向前并拢。', 11)
insert into naruto_spiritism.jutsus (id, name, short_name, category, description, attack_power, color, duration, cover, effect, sort_order) values
('summoning', '通灵之术', '通灵之术', '时空间忍术', '缔结契约，唤醒并肩作战的伙伴。', 0, '#367d65', 5200, '/images/jutsu/summoning.png', 'summoning', 0),
('fireball', '火遁 · 豪火球之术', '豪火球之术', '火遁', '将查克拉凝聚成炽热的火焰。', 55, '#bc493b', 3400, '/images/jutsu/fireball.png', 'fireball', 1),
('chidori', '雷遁 · 千鸟', '千鸟', '雷遁', '千鸟鸣动，雷光汇聚于掌心。', 85, '#337e9c', 3800, '/images/jutsu/chidori.png', 'chidori', 2),
('body-flicker', '瞬身术', '瞬身术', '基础忍术', '将查克拉集中于身体，迅速移动到目标位置。', 0, '#367d65', 0, '/images/ui/paper.svg', null, 3),
('body-replacement', '替身术', '替身术', '基础忍术', '以替代物承受攻击，抓住转移与反击的机会。', 0, '#367d65', 0, '/images/ui/paper.svg', null, 4),
('shuriken-shadow-clone', '手里剑影分身之术', '手里剑影分身之术', '影分身忍术', '为掷出的手里剑创造实体分身，扩大攻击范围。', 50, '#367d65', 0, '/images/ui/paper.svg', null, 5),
('shadow-sewing', '影缝术', '影缝术', '秘传忍术', '让影子化为细长的针状分支，束缚目标的行动。', 25, '#367d65', 0, '/images/ui/paper.svg', null, 6),
('mind-clone-switch', '心转分身之术', '心转分身之术', '秘传忍术', '将精神分为多股，同时进入多个目标的身体。', 0, '#367d65', 0, '/images/ui/paper.svg', null, 7),
('phoenix-sage-fire', '火遁 · 凤仙火之术', '凤仙火之术', '火遁', '连续吐出小型火球，控制火焰追击目标。', 45, '#367d65', 0, '/images/ui/paper.svg', null, 8),
('dragon-fire', '火遁 · 龙火之术', '龙火之术', '火遁', '将火焰凝聚成笔直的火流，沿目标方向喷出。', 60, '#367d65', 0, '/images/ui/paper.svg', null, 9),
('fire-dragon-flame-bullet', '火遁 · 火龙炎弹', '火龙炎弹', '火遁', '吐出龙形烈焰，让火势从多个方向包围目标。', 80, '#367d65', 0, '/images/ui/paper.svg', null, 10),
('ash-pile-burning', '火遁 · 灰积烧', '灰积烧', '火遁', '吐出覆盖周围的灼热烟灰，再引燃烟灰形成爆炎。', 65, '#367d65', 0, '/images/ui/paper.svg', null, 11),
('great-dragon-fire', '火遁 · 豪龙火之术', '豪龙火之术', '火遁', '将查克拉化为龙头形的巨大火焰。', 75, '#367d65', 0, '/images/ui/paper.svg', null, 12),
('intelligent-hard-work', '火遁 · 头刻苦', '头刻苦', '火遁', '释放向地面扩散的烈焰，形成大范围火海。', 85, '#367d65', 0, '/images/ui/paper.svg', null, 13),
('great-fire-annihilation', '火遁 · 豪火灭却', '豪火灭却', '火遁', '以午印凝聚查克拉，释放吞噬一切的烈焰。', 95, '#367d65', 0, '/images/ui/paper.svg', null, 14),
('great-fire-destruction', '火遁 · 豪火灭失', '豪火灭失', '火遁', '吐出铺天盖地的火焰，迅速吞没前方区域。', 100, '#367d65', 0, '/images/ui/paper.svg', null, 15),
('great-breakthrough', '风遁 · 大突破', '大突破', '风遁', '从口中吹出强风，冲击前方的目标。', 35, '#367d65', 0, '/images/ui/paper.svg', null, 16),
('vacuum-sphere', '风遁 · 真空玉', '真空玉', '风遁', '将风凝聚为连续射出的空气弹。', 45, '#367d65', 0, '/images/ui/paper.svg', null, 17),
('vacuum-great-sphere', '风遁 · 真空大玉', '真空大玉', '风遁', '吐出压缩空气形成的巨大风弹。', 70, '#367d65', 0, '/images/ui/paper.svg', null, 18),
('vacuum-wave', '风遁 · 真空波', '真空波', '风遁', '吐出锋利的风刃，横扫前方目标。', 60, '#367d65', 0, '/images/ui/paper.svg', null, 19),
('vacuum-serial-waves', '风遁 · 真空连波', '真空连波', '风遁', '连续释放风刃，形成交错的切割风浪。', 75, '#367d65', 0, '/images/ui/paper.svg', null, 20),
('wind-cutter', '风遁 · 风切之术', '风切之术', '风遁', '让疾风化为利刃，切开前方的障碍。', 55, '#367d65', 0, '/images/ui/paper.svg', null, 21),
('wild-water-wave', '水遁 · 水乱波', '水乱波', '水遁', '将查克拉化为急流，从口中喷出冲击目标。', 40, '#367d65', 0, '/images/ui/paper.svg', null, 22),
('water-bullet', '水遁 · 水弹之术', '水弹之术', '水遁', '将水流压缩成弹状，集中冲击目标。', 50, '#367d65', 0, '/images/ui/paper.svg', null, 23),
('added-weight-rock', '土遁 · 加重岩之术', '加重岩之术', '土遁', '改变接触目标的重量，限制目标的移动。', 0, '#367d65', 0, '/images/ui/paper.svg', null, 24),
('dropping-lid', '土遁 · 落盖之术', '落盖之术', '土遁', '让巨大的盖状岩石从上方落下，压制目标。', 60, '#367d65', 0, '/images/ui/paper.svg', null, 25),
('false-darkness', '雷遁 · 伪暗', '伪暗', '雷遁', '将雷电凝聚为锐利的电流，贯穿目标。', 70, '#367d65', 0, '/images/ui/paper.svg', null, 26),
('black-panther', '雷遁 · 黑斑差', '黑斑差', '雷遁', '让黑色雷电化为豹形，追击前方目标。', 80, '#367d65', 0, '/images/ui/paper.svg', null, 27)
